pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address funder) public {
        // keep the domain wide but admissible: deposit at least 2 wei from a real caller
        amount = bound(amount, 2, type(uint96).max);
        vm.assume(funder != address(0) && funder != address(c) && funder != address(this));

        // funder deposits `amount` via the payable fallback
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool okDep,) = address(c).call{value: amount}("");
