        assertEq(address(c).balance, amount);

        // the owner (the deployer, i.e. this test contract) withdraws everything
        vm.prank(address(this));
        c.withdrawAll();

        // GENERAL RULE: withdrawAll drains the contract completely for every admissible deposit
        assertTrue(address(c).balance == 0);
    }
}

