pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address funder;
    address owner;

    function setUp() public {
        c = new C();
        funder = address(0xA11CE);
        owner = c.owner();
    }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any positive, transferable wei amount.
        amount = bound(amount, 1, type(uint128).max);

        // Fund an external depositor and deposit `amount` via the fallback.
        vm.deal(funder, amount);
        vm.prank(funder);
        c.fallback{value: amount}();

        // The owner drains everything via withdrawAll(); observe the revert flag.
        bool ok;
        vm.prank(owner);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after any deposit, owner's withdrawAll succeeds and
        // empties the contract. The mutant's withdraw transfers nothing, so
        // the balance remains `amount` (nonzero) after withdrawAll.
        assertTrue(ok && address(c).balance == 0);
    }
}

