pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        // exclude BOTH the deployer (owner) and the contract itself so a genuine
        // third party is always in play (a fuzzer can pick address(this) or address(c))
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
